// Generated by tools/voice.py pack. Do not edit: edit RelayStory/MissionCatalog, then regenerate.
// Every voiced line: its bank, region (seconds), speaker, tape treatment and exact on-screen text.
export interface VoiceCue { bank: string; start: number; finish: number; speaker: string; tape: boolean; radio: boolean; text: string }
export const VOICE_CUES: Record<string, VoiceCue> = {
	"story.c00.b00": { bank: "voiceBank01", start: 0.250, finish: 8.269, speaker: "TEAL", tape: true, radio: false, text: "Two taps. That's me. If you're hearing this, I missed a check-in, and you're sitting in my chair because nobody else wanted the paperwork." },
	"story.c00.b01": { bank: "voiceBank01", start: 8.519, finish: 15.793, speaker: "SERA", tape: false, radio: false, text: "He missed three. He told me once: one check-in is weather, two is trouble, three is worry. I've been worried since Tuesday." },
	"story.c00.b02": { bank: "voiceBank01", start: 16.043, finish: 22.958, speaker: "TEAL", tape: true, radio: false, text: "Sparrow. You fly the pattern too low and too fast, and I never fixed it, because it's the only thing you do without asking permission." },
	"story.c00.b03": { bank: "voiceBank01", start: 23.208, finish: 29.025, speaker: "SERA", tape: false, radio: false, text: "Command calls it desertion. They made me say the word on the net. I said it. I'm not saying it again." },
	"story.c00.b04": { bank: "voiceBank01", start: 29.275, finish: 33.624, speaker: "TEAL", tape: true, radio: false, text: "If I miss your checkout, fly the pattern anyway. The sky will still be there." },
	"story.c00.b05": { bank: "voiceBank01", start: 33.874, finish: 37.627, speaker: "TRAINEE", tape: false, radio: false, text: "Three bandits on the rim and an empty chair. Fine. I'll fly the pattern." },
	"story.c01.b00": { bank: "voiceBank01", start: 37.877, finish: 44.445, speaker: "SERA", tape: false, radio: false, text: "The bandits wore our markings. Our paint, our numbers. One of them was a tail I cleared for departure in March." },
	"story.c01.b01": { bank: "voiceBank01", start: 44.695, finish: 51.579, speaker: "SERA", tape: false, radio: false, text: "The quartermaster found a case under Teal's bunk. A coffee tin, twelve tapes, and a note: 'For Sera. Not for the net.'" },
	"story.c01.b02": { bank: "voiceBank01", start: 51.829, finish: 60.527, speaker: "TEAL", tape: true, radio: false, text: "Keep these off the command net. Somebody up there is listening and signing things they shouldn't. If I go quiet, the case goes to Sera. Only Sera." },
	"story.c01.b03": { bank: "voiceBank01", start: 60.777, finish: 68.464, speaker: "TEAL", tape: true, radio: false, text: "There's a manifest in the tin. Aviation fuel, shipped as grain, to five quays on Iron Coast. Nobody ships grain in drums." },
	"story.c01.b04": { bank: "voiceBank01", start: 68.714, finish: 75.115, speaker: "SERA", tape: false, radio: false, text: "Iron Coast is a hundred miles of our own shoreline. Whoever this is, they're not invading. They're already home." },
	"story.c01.b05": { bank: "voiceBank01", start: 75.365, finish: 77.098, speaker: "TRAINEE", tape: false, radio: false, text: "Then I'll go and look at the quays myself." },
	"story.c02.b00": { bank: "voiceBank01", start: 77.348, finish: 83.936, speaker: "TEAL", tape: true, radio: false, text: "I came home through the western switchback. Not the pretty way. The way you take when you don't want to be seen coming home." },
	"story.c02.b01": { bank: "voiceBank01", start: 84.186, finish: 92.491, speaker: "TEAL", tape: true, radio: false, text: "I dropped beacons on the way in. Low power, my own frequency. If anyone ever follows me, I wanted it to be someone who knew the song." },
	"story.c02.b02": { bank: "voiceBank01", start: 92.741, finish: 100.489, speaker: "SERA", tape: false, radio: false, text: "Recovery wanted to walk the canyon for him. Command said no: there are scouts in the rocks, and recovery teams don't carry missiles." },
	"story.c02.b03": { bank: "voiceBank01", start: 100.739, finish: 105.736, speaker: "SERA", tape: false, radio: false, text: "He used to tune that canyon on Sundays. Said it was the only place the tower couldn't talk to him." },
	"story.c02.b04": { bank: "voiceBank01", start: 105.986, finish: 111.949, speaker: "SERA", tape: false, radio: false, text: "Recovery can reach his receiver if you mark it and stay on their frequency. Finding him is work we can do together." },
	"story.c02.b05": { bank: "voiceBank01", start: 112.199, finish: 114.642, speaker: "TRAINEE", tape: false, radio: false, text: "Then that's where he went when he had something to say." },
	"story.c03.b00": { bank: "voiceBank01", start: 114.892, finish: 123.641, speaker: "SERA", tape: false, radio: false, text: "Recovery got into the lower switchback. They found his receiver in the rocks. Cracked case, memory intact. He put it where it would be found." },
	"story.c03.b01": { bank: "voiceBank01", start: 123.891, finish: 132.401, speaker: "TEAL", tape: true, radio: false, text: "There's a radar inside our own training box. Dug into the bowl north of the pass. Nobody signed for it. I checked the ledger three times." },
	"story.c03.b02": { bank: "voiceBank01", start: 132.651, finish: 139.998, speaker: "TEAL", tape: true, radio: false, text: "Somebody wanted to watch trainees. Not the sky. Trainees. Think about why you'd want to know when the kids fly." },
	"story.c03.b03": { bank: "voiceBank01", start: 140.248, finish: 147.684, speaker: "SERA", tape: false, radio: false, text: "If it's real, it's been watching every pattern you've flown for a year. Command wants it gone quietly. I want it photographed first." },
	"story.c03.b04": { bank: "voiceBank01", start: 147.934, finish: 153.877, speaker: "SERA", tape: false, radio: false, text: "The staff list has to reach Varda after the strike. An erased radar can still leave a record nobody can explain away." },
	"story.c03.b05": { bank: "voiceBank01", start: 154.127, finish: 157.936, speaker: "TRAINEE", tape: false, radio: false, text: "If I just blow it up, it's a rumour. If I look at it first, it's a crime." },
	"story.c04.b00": { bank: "voiceBank01", start: 158.186, finish: 167.853, speaker: "TEAL", tape: true, radio: false, text: "The Teklan farmers let me hide a tape in a seed tin. The old woman asked my name, not my rank. Nobody at Varda has asked my name in ten years." },
	"story.c04.b01": { bank: "voiceBank01", start: 168.103, finish: 177.079, speaker: "SERA", tape: false, radio: false, text: "The radar's memory names that orchard. Three days later somebody ordered it evacuated. Now there are patrols firing on the evacuation trucks." },
	"story.c04.b02": { bank: "voiceBank01", start: 177.329, finish: 183.633, speaker: "SERA", tape: false, radio: false, text: "They're not shooting at farmers. They're shooting at a seed tin. That's how badly someone wants Teal's tape back." },
	"story.c04.b03": { bank: "voiceBank01", start: 183.883, finish: 191.005, speaker: "RUSK", tape: false, radio: false, text: "...three officers at Varda are being reassigned tonight. Their names are already off the roster. Nobody will ask. Nobody ever asks." },
	"story.c04.b04": { bank: "voiceBank01", start: 191.255, finish: 197.661, speaker: "SERA", tape: false, radio: false, text: "Count the trucks again at the road. I want names for the beds at Varda, not a report that says most of them got out." },
	"story.c04.b05": { bank: "voiceBank01", start: 197.911, finish: 201.017, speaker: "TRAINEE", tape: false, radio: false, text: "Those trucks are carrying somebody who asked his name. They get out." },
	"story.c05.b00": { bank: "voiceBank01", start: 201.267, finish: 210.423, speaker: "SERA", tape: false, radio: false, text: "The convoy made it. The old woman's granddaughter drove the lead truck. She marked three silos on the map with her thumb. 'Those smell wrong.'" },
	"story.c05.b01": { bank: "voiceBank01", start: 210.673, finish: 218.638, speaker: "TEAL", tape: true, radio: false, text: "Three tanks under grain permits. Aviation fuel. The farmers know the difference, they just can't prove it. A fuel ledger would prove it." },
	"story.c05.b02": { bank: "voiceBank01", start: 218.888, finish: 226.125, speaker: "TEAL", tape: true, radio: false, text: "Sparrow. Every unmarked silo in that valley is somebody's winter. Don't be the one who makes them hungry to make a point." },
	"story.c05.b03": { bank: "voiceBank01", start: 226.375, finish: 231.896, speaker: "SERA", tape: false, radio: false, text: "He wrote that one for you. He never wrote anything for me. I'm choosing not to be hurt by that today." },
	"story.c05.b04": { bank: "voiceBank01", start: 232.146, finish: 239.072, speaker: "SERA", tape: false, radio: false, text: "The farm crew can read the ledger over your radio once the patrol is gone. Fuel burns. The names on the page must survive it." },
	"story.c05.b05": { bank: "voiceBank01", start: 239.322, finish: 241.813, speaker: "TRAINEE", tape: false, radio: false, text: "Three thumbprints. Three fires. Nothing else." },
	"story.c06.b00": { bank: "voiceBank01", start: 242.063, finish: 250.917, speaker: "TEAL", tape: true, radio: false, text: "One courier flies the frequency book through the dust pass every evening. Same time, same whine in the engine. Somebody should fix that bearing." },
	"story.c06.b01": { bank: "voiceBank01", start: 251.167, finish: 259.070, speaker: "SERA", tape: false, radio: false, text: "We pulled his escort code out of the silo radios. Five fighters hide in the dust front with him. They'd rather lose him than drop what he carries." },
	"story.c06.b02": { bank: "voiceBank01", start: 259.320, finish: 264.502, speaker: "SERA", tape: false, radio: false, text: "If the book is real, every relay on the plateau is in it. Every forged voice. Every name." },
	"story.c06.b03": { bank: "voiceBank01", start: 264.752, finish: 272.093, speaker: "SERA", tape: false, radio: false, text: "Scan the clearings before you chase. Then read me the packet on a clean channel; I want its words before command can rewrite them." },
	"story.c06.b04": { bank: "voiceBank01", start: 272.343, finish: 273.286, speaker: "TRAINEE", tape: false, radio: false, text: "Then I'd like to read it." },
	"story.c07.b00": { bank: "voiceBank01", start: 273.536, finish: 282.269, speaker: "SERA", tape: false, radio: false, text: "Not a frequency book. Tomorrow's orders. Varda tower 'compromised', the challenge code changed, my crew 'relieved' at 0400." },
	"story.c07.b01": { bank: "voiceBank01", start: 282.519, finish: 289.256, speaker: "TEAL", tape: true, radio: false, text: "If they ever call our tower compromised, check who changed the challenge code. The tower doesn't go bad. The code does." },
	"story.c07.b02": { bank: "voiceBank01", start: 289.506, finish: 297.687, speaker: "SERA", tape: false, radio: false, text: "They've moved it up. They know we have the packet. Two flights are inbound and my crew is in the tower with a soldering iron and the old code on a napkin." },
	"story.c07.b03": { bank: "voiceBank01", start: 297.937, finish: 301.804, speaker: "SERA", tape: false, radio: false, text: "I'm staying in the tower. In case you were wondering. I'm not leaving my chair for them." },
	"story.c07.b04": { bank: "voiceBank01", start: 302.054, finish: 308.012, speaker: "SERA", tape: false, radio: false, text: "Spotters are using the apron smoke. Mark the dishes first, and stay until our own flights answer the restored tower code." },
	"story.c07.b05": { bank: "voiceBank01", start: 308.262, finish: 310.439, speaker: "TRAINEE", tape: false, radio: false, text: "Keep the lights on, Sera. I'll keep the sky." },
	"story.c08.b00": { bank: "voiceBank01", start: 310.689, finish: 319.012, speaker: "SERA", tape: false, radio: false, text: "The tower is ours again. The old code went out at 0353 and three flights turned around on hearing it. One didn't." },
	"story.c08.b01": { bank: "voiceBank01", start: 319.262, finish: 328.046, speaker: "TEAL", tape: true, radio: false, text: "Vulture Lead followed me into the pass. He wasn't chasing a deserter. You don't chase deserters at night with your lights off. He was erasing a witness." },
	"story.c08.b02": { bank: "voiceBank01", start: 328.296, finish: 334.588, speaker: "TEAL", tape: true, radio: false, text: "He talks on the guard channel when he's hunting. Likes you to know. Don't answer him. Let the canyon answer." },
	"story.c08.b03": { bank: "voiceBank01", start: 334.838, finish: 340.924, speaker: "SERA", tape: false, radio: false, text: "He's searching the night approach for you now. Same lights off. Same voice. He thinks he's finishing a job." },
	"story.c08.b04": { bank: "voiceBank01", start: 341.174, finish: 347.176, speaker: "SERA", tape: false, radio: false, text: "He carries a recorder. Mark where it falls. Recovery should come home with more than another empty aircraft." },
	"story.c08.b05": { bank: "voiceBank01", start: 347.426, finish: 348.273, speaker: "TRAINEE", tape: false, radio: false, text: "He's starting one." },
	"story.c09.b00": { bank: "voiceBank01", start: 348.523, finish: 358.311, speaker: "SERA", tape: false, radio: false, text: "Vulture Lead is down. His recorder survived. He carried relayed 'emergency orders', dozens, every one signed by a governor who's been dead since spring." },
	"story.c09.b01": { bank: "voiceBank01", start: 358.561, finish: 366.050, speaker: "TEAL", tape: true, radio: false, text: "Kiro talks to Lira. Lira talks to Merel. Merel talks to the harbours. Break one link and listen to who screams." },
	"story.c09.b02": { bank: "voiceBank01", start: 366.300, finish: 373.276, speaker: "TEAL", tape: true, radio: false, text: "Kiro keeps an archive. Every forged order, filed, because forgers are vain. It's the only honest thing on the plateau." },
	"story.c09.b03": { bank: "voiceBank02", start: 0.250, finish: 5.826, speaker: "SERA", tape: false, radio: false, text: "I wiped his name off my board this morning. Then I wrote it back. I'm not ready to decide what he is." },
	"story.c09.b04": { bank: "voiceBank02", start: 6.076, finish: 12.854, speaker: "SERA", tape: false, radio: false, text: "Copy the archive before cutting Kiro. If a hidden radar answers, listen to its command channel until we can find it." },
	"story.c09.b05": { bank: "voiceBank02", start: 13.104, finish: 14.209, speaker: "TRAINEE", tape: false, radio: false, text: "I'd like to know what he saw." },
	"story.c10.b00": { bank: "voiceBank02", start: 14.459, finish: 20.001, speaker: "RUSK", tape: false, radio: false, text: "Declare the emergency first. Find the reason after. In a year, nobody has asked me for the reason." },
	"story.c10.b01": { bank: "voiceBank02", start: 20.251, finish: 27.861, speaker: "SERA", tape: false, radio: false, text: "Kiro's archive survived. We have his signing key. But a key alone is a rumour. We need two more stations' logs with the same signature." },
	"story.c10.b02": { bank: "voiceBank02", start: 28.111, finish: 36.652, speaker: "TEAL", tape: true, radio: false, text: "Lira and Merel sit on opposite ridges and hate each other's weather. Lira lies, Merel repeats her. The west ridge still hears the farms." },
	"story.c10.b03": { bank: "voiceBank02", start: 36.902, finish: 42.755, speaker: "SERA", tape: false, radio: false, text: "Three logs, one signature. If his words go out from the west ridge, they reach the people who hid him." },
	"story.c10.b04": { bank: "voiceBank02", start: 43.005, finish: 49.291, speaker: "SERA", tape: false, radio: false, text: "The north farm road has beacons the farmers maintain themselves. If another dish wakes up, that is how you reach it." },
	"story.c10.b05": { bank: "voiceBank02", start: 49.541, finish: 53.495, speaker: "TRAINEE", tape: false, radio: false, text: "His own words, in his own voice, on their own relay. He'd have liked that." },
	"story.c11.b00": { bank: "voiceBank02", start: 53.745, finish: 60.862, speaker: "SERA", tape: false, radio: false, text: "Your packet reached the farms. The old woman heard it in her kitchen. She says Teal sounded tired. She says he always sounded tired." },
	"story.c11.b01": { bank: "voiceBank02", start: 61.112, finish: 70.170, speaker: "SERA", tape: false, radio: false, text: "A loyalist crew has one mobile transmitter on a flatbed. It's the only voice on the plateau that isn't his. They're driving it into the refugee corridor." },
	"story.c11.b02": { bank: "voiceBank02", start: 70.420, finish: 79.887, speaker: "TEAL", tape: true, radio: false, text: "A transmitter on wheels is harder to silence than a voice in a tower. Harder to protect, too. Somebody will have to fly very close to a very slow truck." },
	"story.c11.b03": { bank: "voiceBank02", start: 80.137, finish: 86.942, speaker: "SERA", tape: false, radio: false, text: "If the truck hears a different order, stop it at the fork. Check the mill road, test its new link and bring the relief crew in." },
	"story.c11.b04": { bank: "voiceBank02", start: 87.192, finish: 89.480, speaker: "TRAINEE", tape: false, radio: false, text: "Slow truck. Fast jet. I've done worse maths." },
	"story.c12.b00": { bank: "voiceBank02", start: 89.730, finish: 97.245, speaker: "SERA", tape: false, radio: false, text: "The transmitter is through. Its first reply named four fuel silos and a relay on a 'farm' with a rail siding and no animals." },
	"story.c12.b01": { bank: "voiceBank02", start: 97.495, finish: 105.297, speaker: "TEAL", tape: true, radio: false, text: "They call it a farm because a fuel ledger would show the number of aircraft. The silos with no dust on the ladders. Those are the ones." },
	"story.c12.b02": { bank: "voiceBank02", start: 105.547, finish: 111.748, speaker: "SERA", tape: false, radio: false, text: "There are real houses in that yard. Families who work the siding. I need you to come home with the right number of fires." },
	"story.c12.b03": { bank: "voiceBank02", start: 111.998, finish: 119.340, speaker: "SERA", tape: false, radio: false, text: "The rail crew can copy the fuel ledger while you fly. Stay for their handoff. A burning tank cannot testify, but its ledger can." },
	"story.c12.b04": { bank: "voiceBank02", start: 119.590, finish: 121.853, speaker: "TRAINEE", tape: false, radio: false, text: "Four tanks and a dish. I can count to five." },
	"story.c13.b00": { bank: "voiceBank02", start: 122.103, finish: 131.045, speaker: "TEAL", tape: true, radio: false, text: "There's a saddle where all three arrays can hear you at once. Go and say something true there. Nobody's said anything true on that frequency in a long time." },
	"story.c13.b01": { bank: "voiceBank02", start: 131.295, finish: 137.850, speaker: "SERA", tape: false, radio: false, text: "The staging raid exposed a command frequency. It only reaches the saddle, and the antennas up there are his." },
	"story.c13.b02": { bank: "voiceBank02", start: 138.100, finish: 146.118, speaker: "SERA", tape: false, radio: false, text: "Teal flew that saddle on his checkride. Vulture Two signed the card. I pulled it last night. The handwriting matches the forged orders." },
	"story.c13.b03": { bank: "voiceBank02", start: 146.368, finish: 152.651, speaker: "SERA", tape: false, radio: false, text: "A truck with a dish can replace a dead antenna. Look along the saddle road before we call the chain silent." },
	"story.c13.b04": { bank: "voiceBank02", start: 152.901, finish: 155.929, speaker: "TRAINEE", tape: false, radio: false, text: "Then I'll fly his checkride for him. Properly, this time." },
	"story.c14.b00": { bank: "voiceBank02", start: 156.179, finish: 164.839, speaker: "SERA", tape: false, radio: false, text: "Three stations, one signature. The mobile crew has it on tape with the real governor's death certificate read over the top. It runs thirty-five seconds." },
	"story.c14.b01": { bank: "voiceBank02", start: 165.089, finish: 172.206, speaker: "TEAL", tape: true, radio: false, text: "A clear signal needs time. Don't give them a hero. Give them thirty-five seconds and a hero is beside the point." },
	"story.c14.b02": { bank: "voiceBank02", start: 172.456, finish: 179.820, speaker: "SERA", tape: false, radio: false, text: "He recorded that two weeks before he vanished. Thirty-five seconds. He'd already timed it. He knew exactly what this would take." },
	"story.c14.b03": { bank: "voiceBank02", start: 180.070, finish: 187.619, speaker: "SERA", tape: false, radio: false, text: "When the garrisons answer, follow their beacons and look for parked aircraft. A reply on the radio is not yet a promise kept." },
	"story.c14.b04": { bank: "voiceBank02", start: 187.869, finish: 191.297, speaker: "TRAINEE", tape: false, radio: false, text: "Thirty-five seconds. Nobody jams me for thirty-five seconds." },
	"story.c15.b00": { bank: "voiceBank02", start: 191.547, finish: 196.319, speaker: "SERA", tape: false, radio: false, text: "Three garrisons heard it. Two stood down. And then the Marshal answered." },
	"story.c15.b01": { bank: "voiceBank02", start: 196.569, finish: 204.964, speaker: "RUSK", tape: false, radio: false, text: "Varda Rim has broadcast enemy propaganda. It is a hostile station. The Teklan orchard sheltered the source. There will be no further warnings." },
	"story.c15.b02": { bank: "voiceBank02", start: 205.214, finish: 213.440, speaker: "SERA", tape: false, radio: false, text: "The orchard burned at noon. The old woman is alive. Her granddaughter is alive. The seed tin is ash. That's my report, and I hate it." },
	"story.c15.b03": { bank: "voiceBank02", start: 213.690, finish: 218.398, speaker: "SERA", tape: false, radio: false, text: "I asked you to broadcast. I'd ask again. I need you to know that I'd ask again." },
	"story.c15.b04": { bank: "voiceBank02", start: 218.648, finish: 227.613, speaker: "TEAL", tape: true, radio: false, text: "Storms ground frightened people. They don't ground orders, or fuel, or the people who own them. When the weather's bad, that's when they move." },
	"story.c15.b05": { bank: "voiceBank02", start: 227.863, finish: 234.945, speaker: "SERA", tape: false, radio: false, text: "Rain hides the last fuel markings. Look first. Then stay to copy the relay's final traffic while the farm crew gets clear." },
	"story.c15.b06": { bank: "voiceBank02", start: 235.195, finish: 238.864, speaker: "TRAINEE", tape: false, radio: false, text: "Then he's moving now, under the weather. And I'm going to be under it with him." },
	"story.c16.b00": { bank: "voiceBank02", start: 239.114, finish: 246.749, speaker: "SERA", tape: false, radio: false, text: "His plateau fuel is gone. One relay still talks: the crown station, under the aurora. It only transmits at night." },
	"story.c16.b01": { bank: "voiceBank02", start: 246.999, finish: 256.007, speaker: "TEAL", tape: true, radio: false, text: "At the crown station I left the order that started all of this. The first one. With his real signature, before he learned to use dead men's names." },
	"story.c16.b02": { bank: "voiceBank02", start: 256.257, finish: 261.359, speaker: "TEAL", tape: true, radio: false, text: "I didn't take it with me. I didn't trust myself to get home. I trusted the dish." },
	"story.c16.b03": { bank: "voiceBank02", start: 261.609, finish: 268.619, speaker: "SERA", tape: false, radio: false, text: "He didn't trust himself to get home. He said it out loud, to a tape, and flew anyway. I keep rewinding that part." },
	"story.c16.b04": { bank: "voiceBank02", start: 268.869, finish: 275.545, speaker: "SERA", tape: false, radio: false, text: "If the archive jams, look under the array. We bring home the whole signature this time, even if we have to receive it twice." },
	"story.c16.b05": { bank: "voiceBank02", start: 275.795, finish: 278.219, speaker: "TRAINEE", tape: false, radio: false, text: "He trusted the dish. I can do that much." },
	"story.c17.b00": { bank: "voiceBank02", start: 278.469, finish: 290.794, speaker: "LOG", tape: false, radio: false, text: "ARCHIVE RECOVERED. ORDER 0001. 'Declare regional emergency. Suspend parliament. Assume air command.' Signed: RUSK, AIR MARSHAL." },
	"story.c17.b01": { bank: "voiceBank02", start: 291.044, finish: 297.954, speaker: "SERA", tape: false, radio: false, text: "Rusk. He gave the speech at Teal's wing ceremony. He told us the sky belongs to whoever is willing to be up in it." },
	"story.c17.b02": { bank: "voiceBank02", start: 298.204, finish: 309.781, speaker: "VULTURE TWO", tape: false, radio: false, text: "Varda trainee, this is Vulture Two. I taught your instructor to fly. I know what he'd try from that ridge. Turn home. Nobody has to watch." },
	"story.c17.b03": { bank: "voiceBank02", start: 310.031, finish: 317.865, speaker: "TEAL", tape: true, radio: false, text: "Vulture Two taught me that an order is not the same as a duty. Then he forgot. If you meet him, remind him. Loudly." },
	"story.c17.b04": { bank: "voiceBank02", start: 318.115, finish: 324.494, speaker: "SERA", tape: false, radio: false, text: "He's challenged your call sign from the ridge. Searchlights. He wants you to climb into them. He wants to see your face." },
	"story.c17.b05": { bank: "voiceBank02", start: 324.744, finish: 332.470, speaker: "SERA", tape: false, radio: false, text: "Mark a ridge pickup site before you meet him. If he ejects, the marines need time; the coast needs his testimony after that." },
	"story.c17.b06": { bank: "voiceBank02", start: 332.720, finish: 333.494, speaker: "TRAINEE", tape: false, radio: false, text: "Then he'll see it." },
	"story.c18.b00": { bank: "voiceBank02", start: 333.744, finish: 340.762, speaker: "SERA", tape: false, radio: false, text: "Vulture Two is down. He ejected. Marines lifted him off the ridge. He asked if you were Teal's. I said yes." },
	"story.c18.b01": { bank: "voiceBank02", start: 341.012, finish: 348.756, speaker: "VULTURE TWO", tape: false, radio: false, text: "He was the best I ever signed off. Tell the kid the handwriting was mine. All of it. I'm done lying to pilots." },
	"story.c18.b02": { bank: "voiceBank02", start: 349.006, finish: 354.439, speaker: "TEAL", tape: true, radio: false, text: "On the coast, look at what the cranes unload. The uniforms tell you nothing. The crates do." },
	"story.c18.b03": { bank: "voiceBank02", start: 354.689, finish: 361.724, speaker: "SERA", tape: false, radio: false, text: "Three warehouses on the military quays, two blocks from a fish market. Rusk put his war where he knew we'd hesitate." },
	"story.c18.b04": { bank: "voiceBank02", start: 361.974, finish: 367.948, speaker: "SERA", tape: false, radio: false, text: "Workers are still on those quays. Trace their launch a clear lane and stay for the rescue count after the stores burn." },
	"story.c18.b05": { bank: "voiceBank02", start: 368.198, finish: 370.184, speaker: "TRAINEE", tape: false, radio: false, text: "He's right. I'll hesitate. Then I'll aim." },
	"story.c19.b00": { bank: "voiceBank03", start: 0.250, finish: 8.481, speaker: "TEAL", tape: true, radio: false, text: "I made a paper copy. Radios get jammed. Ink still travels in a boat. It's in the harbour master's safe, and she doesn't like the Marshal either." },
	"story.c19.b01": { bank: "voiceBank03", start: 8.731, finish: 15.919, speaker: "SERA", tape: false, radio: false, text: "The harbour stores are gone. The harbour master has the copy on a courier launch. The eastern wing has the harbour mouth sealed." },
	"story.c19.b02": { bank: "voiceBank03", start: 16.169, finish: 22.709, speaker: "SERA", tape: false, radio: false, text: "Everything we have is on that boat. The archive, the signatures, his tapes. If it sinks, Teal is a deserter forever." },
	"story.c19.b03": { bank: "voiceBank03", start: 22.959, finish: 28.989, speaker: "SERA", tape: false, radio: false, text: "Check the exit before the launch moves. Then stay until the patrol boat confirms the case has changed hands at sea." },
	"story.c19.b04": { bank: "voiceBank03", start: 29.239, finish: 30.025, speaker: "TRAINEE", tape: false, radio: false, text: "It doesn't sink." },
	"story.c20.b00": { bank: "voiceBank03", start: 30.275, finish: 35.356, speaker: "SERA", tape: false, radio: false, text: "The launch is clear. Marines have the evidence. And the city still hears nothing but him." },
	"story.c20.b01": { bank: "voiceBank03", start: 35.606, finish: 42.337, speaker: "RUSK", tape: false, radio: false, text: "Citizens. Parliament has fled. Rebel aircraft are over the harbour. Stay inside. Trust the lights. Trust my voice." },
	"story.c20.b02": { bank: "voiceBank03", start: 42.587, finish: 50.535, speaker: "TEAL", tape: true, radio: false, text: "One tower, one voice, one emergency on repeat. He didn't build it to tell anyone anything. He built it so nothing else gets in." },
	"story.c20.b03": { bank: "voiceBank03", start: 50.785, finish: 57.838, speaker: "SERA", tape: false, radio: false, text: "The broadcast relay sits in a block of apartments. He chose that too. The canal is the only dark line through the city." },
	"story.c20.b04": { bank: "voiceBank03", start: 58.088, finish: 64.714, speaker: "SERA", tape: false, radio: false, text: "Find the dish above the apartments before firing. Our repair crew is waiting in a launch to bring the district back afterwards." },
	"story.c20.b05": { bank: "voiceBank03", start: 64.964, finish: 69.324, speaker: "TRAINEE", tape: false, radio: false, text: "Everyone in those apartments has been listening to him for a year. I'd like to give them some quiet." },
	"story.c21.b00": { bank: "voiceBank03", start: 69.574, finish: 77.367, speaker: "SERA", tape: false, radio: false, text: "The city heard silence last night. First time since spring. People opened their windows. Then the fog came in and he started fuelling." },
	"story.c21.b01": { bank: "voiceBank03", start: 77.617, finish: 85.845, speaker: "TEAL", tape: true, radio: false, text: "The reserve fuel has five piers. Each one has a civilian permit, and every permit has the same signature. He never learned a second name." },
	"story.c21.b02": { bank: "voiceBank03", start: 86.095, finish: 95.893, speaker: "RUSK", tape: false, radio: false, text: "Trainee. I knew Teal. He flew my wing the winter the coast starved while parliament debated. He had talent too. Ask the canyon how far it got him." },
	"story.c21.b03": { bank: "voiceBank03", start: 96.143, finish: 100.401, speaker: "SERA", tape: false, radio: false, text: "That's the first time he's used his own name. He wants you to know he's a person. Don't let him." },
	"story.c21.b04": { bank: "voiceBank03", start: 100.651, finish: 107.482, speaker: "SERA", tape: false, radio: false, text: "An inspection launch will follow you through the fog. Let its crew check the hoses, then show us the last two piers are dry." },
	"story.c21.b05": { bank: "voiceBank03", start: 107.732, finish: 112.014, speaker: "TRAINEE", tape: false, radio: false, text: "He flew your wing. Then you hunted him at night with your lights off. I'll remember both." },
	"story.c22.b00": { bank: "voiceBank03", start: 112.264, finish: 120.863, speaker: "SERA", tape: false, radio: false, text: "His convoy can't refuel. Three loyalist frigates have ringed the offshore platform. The command frigate carries a green beacon and most of our hope." },
	"story.c22.b01": { bank: "voiceBank03", start: 121.113, finish: 127.516, speaker: "TEAL", tape: true, radio: false, text: "If I don't get home, leave the lane open for the next one. That's the job. There isn't a second part." },
	"story.c22.b02": { bank: "voiceBank03", start: 127.766, finish: 134.076, speaker: "SERA", tape: false, radio: false, text: "The frigate captain was at his wing ceremony too. Half this coast was. Rusk forgot that we all remember." },
	"story.c22.b03": { bank: "voiceBank03", start: 134.326, finish: 140.681, speaker: "SERA", tape: false, radio: false, text: "Check the last gap and cover the inspection launch across it. The landing force is waiting for a ring we have actually checked." },
	"story.c22.b04": { bank: "voiceBank03", start: 140.931, finish: 142.957, speaker: "TRAINEE", tape: false, radio: false, text: "Green beacon. I'll stay close enough to read it." },
	"story.c23.b00": { bank: "voiceBank03", start: 143.207, finish: 151.325, speaker: "SERA", tape: false, radio: false, text: "The frigate held. He's pulling his flag off the platform tonight and leaving his reserves on the deck. He's running, and he's leaving the fuel behind." },
	"story.c23.b01": { bank: "voiceBank03", start: 151.575, finish: 157.691, speaker: "TEAL", tape: true, radio: false, text: "Those stores were never on a defence map. You don't hide fuel at sea for a week. Only for a war." },
	"story.c23.b02": { bank: "voiceBank03", start: 157.941, finish: 164.670, speaker: "SERA", tape: false, radio: false, text: "Three stores on a trident of decks, under a storm he didn't order. There's no high approach left. Only the sea." },
	"story.c23.b03": { bank: "voiceBank03", start: 164.920, finish: 171.683, speaker: "SERA", tape: false, radio: false, text: "A tanker is still on the platform, and workers are still on the deck. Stop the fuel leaving, then bring the rescue launch clear." },
	"story.c23.b04": { bank: "voiceBank03", start: 171.933, finish: 175.174, speaker: "TRAINEE", tape: false, radio: false, text: "He said the canyon got Teal. Let's see what the sea does to him." },
	"story.c24.b00": { bank: "voiceBank03", start: 175.424, finish: 183.271, speaker: "SERA", tape: false, radio: false, text: "The platform is dry. Loyalist landing craft are off the city beach, waiting for first light. Parliament is coming home by boat." },
	"story.c24.b01": { bank: "voiceBank03", start: 183.521, finish: 190.163, speaker: "TEAL", tape: true, radio: false, text: "Don't fly for the people giving orders. Fly for the people who have to live beneath them. The man on the net is weather." },
	"story.c24.b02": { bank: "voiceBank03", start: 190.413, finish: 197.032, speaker: "SERA", tape: false, radio: false, text: "He recorded that one at two in the morning. I can hear the hangar heater behind him. I could find that hangar in the dark by that sound." },
	"story.c24.b03": { bank: "voiceBank03", start: 197.282, finish: 203.547, speaker: "SERA", tape: false, radio: false, text: "Check both beach exits between the attacks. Stay on the landing channel until both squads answer from the streets." },
	"story.c24.b04": { bank: "voiceBank03", start: 203.797, finish: 205.970, speaker: "TRAINEE", tape: false, radio: false, text: "Beneath them. Right. The beach, then." },
	"story.c25.b00": { bank: "voiceBank03", start: 206.220, finish: 213.268, speaker: "SERA", tape: false, radio: false, text: "Recovery reached the upper pass this morning. They found his aircraft. They found him. He was in the seat. The recorder was still running." },
	"story.c25.b01": { bank: "voiceBank03", start: 213.518, finish: 217.102, speaker: "RECORDER", tape: true, radio: false, text: "RECORDER 7-T. ENTRY 04:12. PLAYBACK." },
	"story.c25.b02": { bank: "voiceBank03", start: 217.352, finish: 226.255, speaker: "TEAL", tape: true, radio: false, text: "Two taps. Sparrow, it's me. Lead is on my tail and I'm out of altitude, so I'm going to stay in the pass a while. The seed trucks need ten minutes." },
	"story.c25.b03": { bank: "voiceBank03", start: 226.505, finish: 234.301, speaker: "TEAL", tape: true, radio: false, text: "I flew that order knowing the price. The tapes are so you never have to take my word for any of it. This part I'm choosing myself." },
	"story.c25.b04": { bank: "voiceBank03", start: 234.551, finish: 241.285, speaker: "TEAL", tape: true, radio: false, text: "Fly the pattern too low and too fast. Nobody ever fixed it. Good. The sky will..." },
	"story.c25.b05": { bank: "voiceBank03", start: 241.535, finish: 248.253, speaker: "SERA", tape: false, radio: false, text: "He bought those trucks ten minutes. Witnesses are boarding for parliament tonight. Keep their quay and launch safe so they can say what he did." },
	"story.c25.b06": { bank: "voiceBank03", start: 248.503, finish: 255.815, speaker: "SERA", tape: false, radio: false, text: "I've amended the record myself. 'Aircraft lost with pilot. KILLED, NOT DESERTED.' Command can court-martial the paperwork." },
	"story.c25.b07": { bank: "voiceBank03", start: 256.065, finish: 259.198, speaker: "TRAINEE", tape: false, radio: false, text: "Ten minutes. He bought ten minutes. I'm going to go and spend them." },
	"story.c26.b00": { bank: "voiceBank03", start: 259.448, finish: 267.510, speaker: "SERA", tape: false, radio: false, text: "The wing is broken. Your triangulation puts his last transmission above the parliament tower. He's alone up there with one relay and his own voice." },
	"story.c26.b01": { bank: "voiceBank03", start: 267.760, finish: 275.179, speaker: "RUSK", tape: false, radio: false, text: "Trainee. Land, and I'll tell the city you were misled by a dead man. Fly, and you're the traitor in every history I write." },
	"story.c26.b02": { bank: "voiceBank03", start: 275.429, finish: 280.523, speaker: "TEAL", tape: true, radio: false, text: "When you have the truth, send it in your own voice. You don't have to sound like me. You never did." },
	"story.c26.b03": { bank: "voiceBank03", start: 280.773, finish: 288.247, speaker: "SERA", tape: false, radio: false, text: "I've got every harbour on the net. Every loyalist station is listening for one call sign. Not his. Yours." },
	"story.c26.b04": { bank: "voiceBank03", start: 288.497, finish: 295.402, speaker: "SERA", tape: false, radio: false, text: "Mark a clear road for Rusk before the duel. Then climb Teal's beacon line and stay on the air until every harbor hears you." },
	"story.c26.b05": { bank: "voiceBank03", start: 295.652, finish: 300.350, speaker: "TRAINEE", tape: false, radio: false, text: "Marshal. I heard the tape. He didn't sound misled. He sounded like he was counting trucks." },
	"story.c26.b06": { bank: "voiceBank03", start: 300.600, finish: 305.035, speaker: "TRAINEE", tape: false, radio: false, text: "Sera. Varda trainee, checking in. One of three. The other two are for after." },
	"story.c27.b00": { bank: "voiceBank03", start: 305.285, finish: 313.763, speaker: "SERA", tape: false, radio: false, text: "He's down. His relay is dark. Every harbour on the coast is answering. You're on every receiver from the rim to the sea. Say it your way." },
	"story.c27.b01": { bank: "voiceBank03", start: 314.013, finish: 320.424, speaker: "TRAINEE", tape: false, radio: false, text: "This is Varda trainee, transmitting in the clear. The Air Marshal is down. The emergency is over. It never started." },
	"story.c27.b02": { bank: "voiceBank03", start: 320.674, finish: 328.232, speaker: "TRAINEE", tape: false, radio: false, text: "The orders were forged. The names were dead men's. An orchard was burned for a seed tin. Teal flew the pass so the trucks could get out." },
	"story.c27.b03": { bank: "voiceBank03", start: 328.482, finish: 336.027, speaker: "TRAINEE", tape: false, radio: false, text: "His name was Teal. He was not a deserter. Amend your records. For Teal. For the rim. We are coming home." },
	"story.c27.b04": { bank: "voiceBank03", start: 336.277, finish: 342.851, speaker: "SERA", tape: false, radio: false, text: "Varda trainee, Varda Control. Check-in received. Two of three. Come home and make the third in person." },
	"story.c27.b05": { bank: "voiceBank03", start: 343.101, finish: 344.566, speaker: "TEAL", tape: true, radio: false, text: "...the sky will still be there." },
	"story.c27.b06": { bank: "voiceBank03", start: 344.816, finish: 351.844, speaker: "LOG", tape: false, radio: false, text: "VARDA RIM ROSTER. TEAL: KILLED IN ACTION, NOT DESERTED. INSTRUCTOR'S CHAIR: FILLED." },
	"radio.m01.p1.beat": { bank: "voiceBank03", start: 352.094, finish: 355.871, speaker: "SERA", tape: false, radio: true, text: "Turn, then pitch. Three seconds each. Feel how she answers." },
	"radio.m01.p2.beat": { bank: "voiceBank03", start: 356.121, finish: 358.560, speaker: "SERA", tape: false, radio: true, text: "Cycle targets. Mark the practice radar." },
	"radio.m01.p3.beat": { bank: "voiceBank03", start: 358.810, finish: 360.844, speaker: "SERA", tape: false, radio: true, text: "Nose on it. Hold the lock. Then fire." },
	"radio.m01.p4.beat": { bank: "voiceBank03", start: 361.094, finish: 364.075, speaker: "SERA", tape: false, radio: true, text: "SERA: Good hit. Three bandits inbound. Keep them off the field." },
	"radio.m02.p1.beat": { bank: "voiceBank03", start: 364.325, finish: 366.196, speaker: "SERA", tape: false, radio: true, text: "SERA: Three bandits over the harbor. Take them." },
	"radio.m02.p2.beat": { bank: "voiceBank03", start: 366.446, finish: 369.021, speaker: "SERA", tape: false, radio: true, text: "SERA: Five warehouses feed the raid. Burn them all." },
	"radio.m02.p3.beat": { bank: "voiceBank03", start: 369.271, finish: 371.531, speaker: "SERA", tape: false, radio: true, text: "SERA: Their lead is armored. Make every shot count." },
	"radio.m03.p1.beat": { bank: "voiceBank03", start: 371.781, finish: 373.307, speaker: "TEAL", tape: true, radio: true, text: "TEAL (tape): Stay low on the switchback." },
	"radio.m03.p1.chatter1": { bank: "voiceBank04", start: 0.250, finish: 2.268, speaker: "TEAL", tape: true, radio: true, text: "TEAL (tape): Third beacon's the one I nearly missed." },
	"radio.m03.p2.beat": { bank: "voiceBank04", start: 2.518, finish: 5.687, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan below the beacons. Recovery needs the receiver marked." },
	"radio.m03.p2.chatter1": { bank: "voiceBank04", start: 5.937, finish: 8.644, speaker: "SERA", tape: false, radio: true, text: "SERA: Receiver echo below the second beacon. Keep scanning." },
	"radio.m03.p3.beat": { bank: "voiceBank04", start: 8.894, finish: 11.244, speaker: "SERA", tape: false, radio: true, text: "SERA: Two scouts shadowing the rim. Clear the pair." },
	"radio.m03.p4.beat": { bank: "voiceBank04", start: 11.494, finish: 14.905, speaker: "TEAL", tape: true, radio: true, text: "TEAL (tape): Under three-twenty along the river. Stay out of sight." },
	"radio.m03.p4.chatter1": { bank: "voiceBank04", start: 15.155, finish: 18.424, speaker: "SERA", tape: false, radio: true, text: "SERA: Bravo flight is hunting the river. Last gate, then turn." },
	"radio.m03.p5.beat": { bank: "voiceBank04", start: 18.674, finish: 21.822, speaker: "SERA", tape: false, radio: true, text: "SERA: Bravo flight breaking cover. Three, in two groups. Clear them." },
	"radio.m03.p6.beat": { bank: "voiceBank04", start: 22.072, finish: 24.997, speaker: "RECOVERY", tape: false, radio: true, text: "RECOVERY: We have your mark. Keep the link open while we reach it." },
	"radio.m03.p6.chatter1": { bank: "voiceBank04", start: 25.247, finish: 27.426, speaker: "RECOVERY", tape: false, radio: true, text: "RECOVERY: Receiver in sight. We are climbing down now." },
	"radio.m04.p1.beat": { bank: "voiceBank04", start: 27.676, finish: 31.537, speaker: "BROADCAST", tape: false, radio: true, text: "BROADCAST: All Varda units stand down. Authority: Air Marshal." },
	"radio.m04.p1.chatter1": { bank: "voiceBank04", start: 31.787, finish: 33.879, speaker: "SERA", tape: false, radio: true, text: "SERA: Stand down? Nobody at Varda issued that." },
	"radio.m04.p2.beat": { bank: "voiceBank04", start: 34.129, finish: 36.012, speaker: "SERA", tape: false, radio: true, text: "SERA: Proof's recorded. Now kill the radar." },
	"radio.m04.p3.beat": { bank: "voiceBank04", start: 36.262, finish: 38.785, speaker: "SERA", tape: false, radio: true, text: "SERA: Evidence copied. Follow the service road clear." },
	"radio.m04.p3.chatter1": { bank: "voiceBank04", start: 39.035, finish: 41.109, speaker: "SERA", tape: false, radio: true, text: "SERA: Road is clear ahead. Keep to the beacon line." },
	"radio.m04.p4.beat": { bank: "voiceBank04", start: 41.359, finish: 45.031, speaker: "SERA", tape: false, radio: true, text: "SERA: They scrambled a flight. Five, in two groups. Hold the line." },
	"radio.m04.p5.beat": { bank: "voiceBank04", start: 45.281, finish: 47.617, speaker: "SERA", tape: false, radio: true, text: "SERA: Varda is copying the names. Hold the link." },
	"radio.m04.p5.chatter1": { bank: "voiceBank04", start: 47.867, finish: 50.425, speaker: "TOWER", tape: false, radio: true, text: "TOWER: First two names copied. Send the third." },
	"radio.m05.p1.beat": { bank: "voiceBank04", start: 50.675, finish: 52.657, speaker: "FARMER", tape: false, radio: true, text: "FARMER: Trucks rolling. Please stay with us." },
	"radio.m05.p1.chatter1": { bank: "voiceBank04", start: 52.907, finish: 54.899, speaker: "SERA", tape: false, radio: true, text: "SERA: Second flight off the ridge. Turn back now." },
	"radio.m05.p1.chatter2": { bank: "voiceBank04", start: 55.149, finish: 57.133, speaker: "FARMER", tape: false, radio: true, text: "FARMER: The road's in sight. Don't leave us yet." },
	"radio.m05.p2.beat": { bank: "voiceBank04", start: 57.383, finish: 60.534, speaker: "SERA", tape: false, radio: true, text: "SERA: Trucks are clear. Their patrol leads are turning in. Three." },
	"radio.m05.p3.beat": { bank: "voiceBank04", start: 60.784, finish: 64.139, speaker: "FARMER", tape: false, radio: true, text: "FARMER: One truck lost its radio. Check both bends for stragglers." },
	"radio.m05.p3.chatter1": { bank: "voiceBank04", start: 64.389, finish: 67.083, speaker: "FARMER", tape: false, radio: true, text: "FARMER: One bend clear. Check behind the orchard wall too." },
	"radio.m05.p4.beat": { bank: "voiceBank04", start: 67.333, finish: 70.379, speaker: "SERA", tape: false, radio: true, text: "SERA: All trucks counted. Hold the link for the families' names." },
	"radio.m05.p4.chatter1": { bank: "voiceBank04", start: 70.629, finish: 73.889, speaker: "TOWER", tape: false, radio: true, text: "TOWER: Names copied. Finding beds for the children now." },
	"radio.m05.p5.beat": { bank: "voiceBank04", start: 74.139, finish: 77.391, speaker: "FARMER", tape: false, radio: true, text: "FARMER: Seed tin is aboard. Follow our homeward beacons." },
	"radio.m05.p5.chatter1": { bank: "voiceBank04", start: 77.641, finish: 79.738, speaker: "FARMER", tape: false, radio: true, text: "FARMER: The lead truck sees your lights. Keep leading." },
	"radio.m06.p1.beat": { bank: "voiceBank04", start: 79.988, finish: 82.555, speaker: "SERA", tape: false, radio: true, text: "SERA: Follow the channel. The marked tanks sit at its end." },
	"radio.m06.p1.chatter1": { bank: "voiceBank04", start: 82.805, finish: 84.950, speaker: "FARMER", tape: false, radio: true, text: "FARMER: The unmarked roofs are ours. Please." },
	"radio.m06.p2.beat": { bank: "voiceBank04", start: 85.200, finish: 88.682, speaker: "SERA", tape: false, radio: true, text: "SERA: Low pass first. Mark the military silos, not the farmhouses." },
	"radio.m06.p2.chatter1": { bank: "voiceBank04", start: 88.932, finish: 91.810, speaker: "SERA", tape: false, radio: true, text: "SERA: Fuel-grade grain in all three. The roofs are clean." },
	"radio.m06.p3.beat": { bank: "voiceBank04", start: 92.060, finish: 94.291, speaker: "SERA", tape: false, radio: true, text: "SERA: Marked silos only. That grain is fuel." },
	"radio.m06.p4.beat": { bank: "voiceBank04", start: 94.541, finish: 97.849, speaker: "SERA", tape: false, radio: true, text: "SERA: Five answering the smoke, in two groups. Turn into them." },
	"radio.m06.p5.beat": { bank: "voiceBank04", start: 98.099, finish: 101.140, speaker: "SERA", tape: false, radio: true, text: "SERA: The farm crew found the ledger. Hold the link while they read it." },
	"radio.m06.p5.chatter1": { bank: "voiceBank04", start: 101.390, finish: 104.700, speaker: "FARMER", tape: false, radio: true, text: "FARMER: Three fuel shipments. All signed by the same officer." },
	"radio.m07.p1.beat": { bank: "voiceBank04", start: 104.950, finish: 107.433, speaker: "SERA", tape: false, radio: true, text: "SERA: The courier runs under the dust. Stay in it." },
	"radio.m07.p1.chatter1": { bank: "voiceBank04", start: 107.683, finish: 109.985, speaker: "SERA", tape: false, radio: true, text: "SERA: Five escorts ahead of him. Dust is thinning." },
	"radio.m07.p2.beat": { bank: "voiceBank04", start: 110.235, finish: 112.259, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan both clearings for his engine trail." },
	"radio.m07.p2.chatter1": { bank: "voiceBank04", start: 112.509, finish: 114.698, speaker: "SERA", tape: false, radio: true, text: "SERA: Engine trail at the second clearing. Keep low." },
	"radio.m07.p3.beat": { bank: "voiceBank04", start: 114.948, finish: 118.331, speaker: "SERA", tape: false, radio: true, text: "SERA: Five escorts in the dust, in two groups. Strip them off him." },
	"radio.m07.p4.beat": { bank: "voiceBank04", start: 118.581, finish: 121.710, speaker: "SERA", tape: false, radio: true, text: "SERA: There's the courier, running north. Ninety seconds. Catch him." },
	"radio.m07.p4.chatter1": { bank: "voiceBank04", start: 121.960, finish: 124.024, speaker: "SERA", tape: false, radio: true, text: "SERA: He's halfway to the plateau. Close on him." },
	"radio.m07.p4.chatter2": { bank: "voiceBank04", start: 124.274, finish: 126.027, speaker: "SERA", tape: false, radio: true, text: "SERA: Twenty seconds and he's over the edge!" },
	"radio.m07.p5.beat": { bank: "voiceBank04", start: 126.277, finish: 129.243, speaker: "SERA", tape: false, radio: true, text: "SERA: Packet recovered. Head for Varda while I read the orders." },
	"radio.m07.p5.chatter1": { bank: "voiceBank04", start: 129.493, finish: 132.606, speaker: "SERA", tape: false, radio: true, text: "SERA: Tomorrow's orders copied. Reading the signatures next." },
	"radio.m08.p1.beat": { bank: "voiceBank04", start: 132.856, finish: 135.970, speaker: "SERA", tape: false, radio: true, text: "SERA: Tower crew resetting the code. Keep the raiders off them." },
	"radio.m08.p1.chatter1": { bank: "voiceBank04", start: 136.220, finish: 139.061, speaker: "BROADCAST", tape: false, radio: true, text: "BROADCAST: Varda tower is in rebel hands. Fire on it." },
	"radio.m08.p1.chatter2": { bank: "voiceBank04", start: 139.311, finish: 140.484, speaker: "SERA", tape: false, radio: true, text: "SERA: Ignore that. It's him." },
	"radio.m08.p1.chatter3": { bank: "voiceBank04", start: 140.734, finish: 143.479, speaker: "SERA", tape: false, radio: true, text: "SERA: Second wave's dropping smoke on the apron. Spotters." },
	"radio.m08.p2.beat": { bank: "voiceBank04", start: 143.729, finish: 147.034, speaker: "SERA", tape: false, radio: true, text: "SERA: Smoke on the apron. Scan for the two spotter dishes first." },
	"radio.m08.p2.chatter1": { bank: "voiceBank04", start: 147.284, finish: 150.195, speaker: "SERA", tape: false, radio: true, text: "SERA: Two dishes in the smoke. Keep the parked trainers clear." },
	"radio.m08.p3.beat": { bank: "voiceBank04", start: 150.445, finish: 153.789, speaker: "SERA", tape: false, radio: true, text: "SERA: Code is ours. Two spotter radars on the apron. Hit them." },
	"radio.m08.p4.beat": { bank: "voiceBank04", start: 154.039, finish: 156.977, speaker: "SERA", tape: false, radio: true, text: "SERA: Spotters down. Their flight is running. Catch three." },
	"radio.m08.p5.beat": { bank: "voiceBank04", start: 157.227, finish: 161.514, speaker: "TOWER", tape: false, radio: true, text: "TOWER: Code restored. Stay on the link until every loyal flight answers." },
	"radio.m08.p5.chatter1": { bank: "voiceBank04", start: 161.764, finish: 164.480, speaker: "TOWER", tape: false, radio: true, text: "TOWER: Loyal flight answering. Waiting on the last one." },
	"radio.m09.p1.beat": { bank: "voiceBank04", start: 164.730, finish: 166.912, speaker: "SERA", tape: false, radio: true, text: "SERA: The approach lights are his bait. Fly them anyway." },
	"radio.m09.p1.chatter1": { bank: "voiceBank04", start: 167.162, finish: 169.528, speaker: "VULTURE LEAD", tape: false, radio: true, text: "VULTURE LEAD: Teal flew this line too. Keep coming." },
	"radio.m09.p2.beat": { bank: "voiceBank04", start: 169.778, finish: 173.134, speaker: "SERA", tape: false, radio: true, text: "SERA: His voice is bouncing off the pass. Scan low to mark the source." },
	"radio.m09.p2.chatter1": { bank: "voiceBank04", start: 173.384, finish: 175.958, speaker: "SERA", tape: false, radio: true, text: "SERA: Guard-channel source above the pass. That is him." },
	"radio.m09.p3.beat": { bank: "voiceBank04", start: 176.208, finish: 179.427, speaker: "SERA", tape: false, radio: true, text: "SERA: Three on night vision, in two groups. Watch your horizon." },
	"radio.m09.p4.beat": { bank: "voiceBank04", start: 179.677, finish: 182.623, speaker: "SERA", tape: false, radio: true, text: "SERA: Patrol is gone. Hold the channel open. He will come to answer." },
	"radio.m09.p4.chatter1": { bank: "voiceBank04", start: 182.873, finish: 185.227, speaker: "VULTURE LEAD", tape: false, radio: true, text: "VULTURE LEAD: You have my attention, trainee. Stay there." },
	"radio.m09.p5.beat": { bank: "voiceBank04", start: 185.477, finish: 188.647, speaker: "SERA", tape: false, radio: true, text: "Vulture Lead. He erased the witness. Not you." },
	"radio.m09.p6.beat": { bank: "voiceBank04", start: 188.897, finish: 192.240, speaker: "RECOVERY", tape: false, radio: true, text: "RECOVERY: Recorder still transmitting. Mark it before the signal dies." },
	"radio.m09.p6.chatter1": { bank: "voiceBank04", start: 192.490, finish: 195.128, speaker: "RECOVERY", tape: false, radio: true, text: "RECOVERY: Recorder ping steady. Mark the second slope." },
	"radio.m09.ace.stage1": { bank: "voiceBank04", start: 195.378, finish: 198.964, speaker: "VULTURE LEAD", tape: false, radio: true, text: "VULTURE LEAD: You fly like him. He died anyway. Wing, cut him off." },
	"radio.m09.ace.stage2": { bank: "voiceBank04", start: 199.214, finish: 200.587, speaker: "VULTURE LEAD", tape: false, radio: true, text: "VULTURE LEAD: Enough. Wing, on me!" },
	"radio.m09.ace.return1": { bank: "voiceBank04", start: 200.837, finish: 203.148, speaker: "SERA", tape: false, radio: true, text: "SERA: Vulture Lead's turning back in. Nose on him." },
	"radio.m09.ace.return2": { bank: "voiceBank04", start: 203.398, finish: 205.237, speaker: "VULTURE LEAD", tape: false, radio: true, text: "VULTURE LEAD: Head on, trainee. Like he did." },
	"radio.m09.ace.call1": { bank: "voiceBank04", start: 205.487, finish: 208.322, speaker: "SERA", tape: false, radio: true, text: "SERA: VULTURE LEAD pulled back to call his wing. 1 inbound." },
	"radio.m09.ace.call2": { bank: "voiceBank04", start: 208.572, finish: 211.835, speaker: "SERA", tape: false, radio: true, text: "SERA: VULTURE LEAD pulled back to call his wing. 2 inbound." },
	"radio.m10.p1.beat": { bank: "voiceBank04", start: 212.085, finish: 214.206, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan the archive first. The dish can wait." },
	"radio.m10.p1.chatter1": { bank: "voiceBank04", start: 214.456, finish: 216.863, speaker: "SERA", tape: false, radio: true, text: "SERA: Signatures copying. Stay low. Hold fire." },
	"radio.m10.p1.twist": { bank: "voiceBank04", start: 217.113, finish: 220.267, speaker: "SERA", tape: false, radio: true, text: "SERA: They've seen you. Four climbing off the camp. Scan's on hold." },
	"radio.m10.p1.t1.beat": { bank: "voiceBank04", start: 220.517, finish: 223.986, speaker: "SERA", tape: false, radio: true, text: "SERA: Four off the camp, in pairs. Clear them, then we finish the scan." },
	"radio.m10.p1.t2.beat": { bank: "voiceBank04", start: 224.236, finish: 226.897, speaker: "SERA", tape: false, radio: true, text: "SERA: Back on the archive. Eight seconds of clean copy." },
	"radio.m10.p1.t2.chatter1": { bank: "voiceBank04", start: 227.147, finish: 229.214, speaker: "SERA", tape: false, radio: true, text: "SERA: Copy complete in four. Hold your line." },
	"radio.m10.p2.beat": { bank: "voiceBank04", start: 229.464, finish: 231.478, speaker: "SERA", tape: false, radio: true, text: "SERA: Archive copied. Cut the transmitter." },
	"radio.m10.p2.twist": { bank: "voiceBank04", start: 231.728, finish: 234.434, speaker: "SERA", tape: false, radio: true, text: "SERA: Radar is directing them. Hold the channel; we will trace it." },
	"radio.m10.p2.t1.beat": { bank: "voiceBank04", start: 234.684, finish: 236.815, speaker: "SERA", tape: false, radio: true, text: "SERA: Hold the channel while we trace the camp radar." },
	"radio.m10.p2.t1.chatter1": { bank: "voiceBank04", start: 237.065, finish: 239.646, speaker: "SERA", tape: false, radio: true, text: "SERA: The radar is still directing them. Trace is closing." },
	"radio.m10.p2.t2.beat": { bank: "voiceBank04", start: 239.896, finish: 243.847, speaker: "SERA", tape: false, radio: true, text: "SERA: Radar on the camp roof. Its raiders fire twice as fast. Kill it." },
	"radio.m10.p3.beat": { bank: "voiceBank04", start: 244.097, finish: 247.228, speaker: "SERA", tape: false, radio: true, text: "SERA: Radar's dead. The response is flying blind. Three." },
	"radio.m11.p1.beat": { bank: "voiceBank04", start: 247.478, finish: 249.108, speaker: "SERA", tape: false, radio: true, text: "SERA: Lira first. West ridge dish." },
	"radio.m11.p2.beat": { bank: "voiceBank04", start: 249.358, finish: 251.504, speaker: "SERA", tape: false, radio: true, text: "SERA: Alert flight airborne. Three. Clear them." },
	"radio.m11.p3.beat": { bank: "voiceBank04", start: 251.754, finish: 253.266, speaker: "SERA", tape: false, radio: true, text: "SERA: Merel next. East ridge." },
	"radio.m11.p3.twist": { bank: "voiceBank04", start: 253.516, finish: 256.697, speaker: "SERA", tape: false, radio: true, text: "SERA: Third dish lit north of the belt. Node Sable. Not on the tin." },
	"radio.m11.p3.t1.beat": { bank: "voiceBank04", start: 256.947, finish: 259.199, speaker: "SERA", tape: false, radio: true, text: "SERA: Farm road north. Two beacons to Sable." },
	"radio.m11.p3.t1.chatter1": { bank: "voiceBank04", start: 259.449, finish: 261.835, speaker: "FARMER", tape: false, radio: true, text: "FARMER: That dish went up last week. Nobody asked us." },
	"radio.m11.p3.t2.beat": { bank: "voiceBank04", start: 262.085, finish: 265.015, speaker: "SERA", tape: false, radio: true, text: "SERA: Sable. Dish only. The barn beside it is ours." },
	"radio.m11.p3.t3.beat": { bank: "voiceBank04", start: 265.265, finish: 266.857, speaker: "SERA", tape: false, radio: true, text: "SERA: Guard flight off Sable. Three." },
	"radio.m11.p4.beat": { bank: "voiceBank04", start: 267.107, finish: 270.143, speaker: "SERA", tape: false, radio: true, text: "SERA: Relaying Teal's packet. Ninety seconds. Hold the ridge orbit." },
	"radio.m11.p4.chatter1": { bank: "voiceBank04", start: 270.393, finish: 272.086, speaker: "FARMER", tape: false, radio: true, text: "FARMER: We're hearing it. Keep it coming." },
	"radio.m11.p4.chatter2": { bank: "voiceBank04", start: 272.336, finish: 274.634, speaker: "SERA", tape: false, radio: true, text: "SERA: Last of the packet. Don't drift off the ridge." },
	"radio.m12.p1.beat": { bank: "voiceBank04", start: 274.884, finish: 277.883, speaker: "TRUCK", tape: false, radio: true, text: "TRUCK: Transmitter rolling. The corridor is full of refugees." },
	"radio.m12.p1.chatter1": { bank: "voiceBank04", start: 278.133, finish: 279.687, speaker: "SERA", tape: false, radio: true, text: "SERA: Second flight coming for the truck." },
	"radio.m12.p1.twist": { bank: "voiceBank04", start: 279.937, finish: 284.042, speaker: "BROADCAST", tape: false, radio: true, text: "BROADCAST: Convoy, the north corridor is clear. Proceed north at speed." },
	"radio.m12.p1.t1.beat": { bank: "voiceBank04", start: 284.292, finish: 287.364, speaker: "SERA", tape: false, radio: true, text: "SERA: Ignore him. North is mined. Truck, stop. Scan the mill road." },
	"radio.m12.p1.t1.chatter1": { bank: "voiceBank04", start: 287.614, finish: 290.401, speaker: "SERA", tape: false, radio: true, text: "SERA: Refugees clear of the bend. One more look at the road." },
	"radio.m12.p1.t2.beat": { bank: "voiceBank04", start: 290.651, finish: 293.624, speaker: "SERA", tape: false, radio: true, text: "SERA: Mill road is clear. Truck, swing east. We will cover you." },
	"radio.m12.p1.t2.chatter1": { bank: "voiceBank04", start: 293.874, finish: 296.201, speaker: "TRUCK", tape: false, radio: true, text: "TRUCK: Mill road's rough but we're moving. Stay with us." },
	"radio.m12.p2.beat": { bank: "voiceBank04", start: 296.451, finish: 299.455, speaker: "SERA", tape: false, radio: true, text: "SERA: Truck's clear. Patrol escalating. Six, in two groups." },
	"radio.m12.p3.beat": { bank: "voiceBank04", start: 299.705, finish: 303.153, speaker: "TRUCK", tape: false, radio: true, text: "TRUCK: Parked and transmitting. Hold for our first reply." },
	"radio.m12.p3.chatter1": { bank: "voiceBank04", start: 303.403, finish: 305.992, speaker: "TRUCK", tape: false, radio: true, text: "TRUCK: First loyalist cell answering. Holding for the second." },
	"radio.m12.p4.beat": { bank: "voiceBank04", start: 306.242, finish: 309.089, speaker: "SERA", tape: false, radio: true, text: "SERA: Relief crew following your beacons. Bring them to the truck." },
	"radio.m12.p4.chatter1": { bank: "voiceBank04", start: 309.339, finish: 312.130, speaker: "SERA", tape: false, radio: true, text: "SERA: Relief crew sees the transmitter. Last beacon ahead." },
	"radio.m13.p1.beat": { bank: "voiceBank04", start: 312.380, finish: 315.069, speaker: "SERA", tape: false, radio: true, text: "SERA: Rail spur runs straight to their stores. Follow it." },
	"radio.m13.p1.chatter1": { bank: "voiceBank04", start: 315.319, finish: 317.857, speaker: "SERA", tape: false, radio: true, text: "SERA: Spur ends at the silos. Low and quiet now." },
	"radio.m13.p2.beat": { bank: "voiceBank04", start: 318.107, finish: 320.597, speaker: "SERA", tape: false, radio: true, text: "SERA: Mark the stores. Civilian roofs stay standing." },
	"radio.m13.p2.chatter1": { bank: "voiceBank04", start: 320.847, finish: 323.567, speaker: "SERA", tape: false, radio: true, text: "SERA: Fuel ledger confirmed. Those silos are military." },
	"radio.m13.p3.beat": { bank: "voiceBank04", start: 323.817, finish: 325.583, speaker: "SERA", tape: false, radio: true, text: "SERA: Four silos. Marked only." },
	"radio.m13.p3.twist": { bank: "voiceBank04", start: 325.833, finish: 328.820, speaker: "SERA", tape: false, radio: true, text: "SERA: Four off the plateau. Finish the silos, then turn into them." },
	"radio.m13.p3.t1.beat": { bank: "voiceBank04", start: 329.070, finish: 332.135, speaker: "SERA", tape: false, radio: true, text: "SERA: Silos burning. Now the four, in pairs. Turn in." },
	"radio.m13.p4.beat": { bank: "voiceBank04", start: 332.385, finish: 334.222, speaker: "SERA", tape: false, radio: true, text: "SERA: The relay's still calling for help. Cut it." },
	"radio.m13.p5.beat": { bank: "voiceBank04", start: 334.472, finish: 337.446, speaker: "SERA", tape: false, radio: true, text: "SERA: Raiders off the plateau. Three more, with hangers-on." },
	"radio.m13.p6.beat": { bank: "voiceBank04", start: 337.696, finish: 340.623, speaker: "SERA", tape: false, radio: true, text: "SERA: Rail crew has the ledger. Hold the link to the cells." },
	"radio.m13.p6.chatter1": { bank: "voiceBank04", start: 340.873, finish: 343.708, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: Rail ledger copied. Matching it against Kiro's orders." },
	"radio.m14.p1.beat": { bank: "voiceBank04", start: 343.958, finish: 345.965, speaker: "SERA", tape: false, radio: true, text: "SERA: Saddle beacons lead to the arrays. Climb." },
	"radio.m14.p1.chatter1": { bank: "voiceBank04", start: 346.215, finish: 347.898, speaker: "SERA", tape: false, radio: true, text: "SERA: All three arrays can hear you now." },
	"radio.m14.p1.chatter2": { bank: "voiceBank04", start: 348.148, finish: 350.996, speaker: "BROADCAST", tape: false, radio: true, text: "BROADCAST: Unknown aircraft on the saddle. Intercept." },
	"radio.m14.p2.beat": { bank: "voiceBank04", start: 351.246, finish: 353.051, speaker: "SERA", tape: false, radio: true, text: "SERA: Three dishes on the ridge. Blind them." },
	"radio.m14.p2.twist": { bank: "voiceBank04", start: 353.301, finish: 356.088, speaker: "SERA", tape: false, radio: true, text: "SERA: Replacement mast on the saddle road. Cut that one too." },
	"radio.m14.p2.t1.beat": { bank: "voiceBank04", start: 356.338, finish: 359.156, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan the saddle road. They have raised a replacement dish." },
	"radio.m14.p2.t1.chatter1": { bank: "voiceBank04", start: 359.406, finish: 362.388, speaker: "SERA", tape: false, radio: true, text: "SERA: Dish truck on the saddle road. Civilian vans are clear." },
	"radio.m14.p2.t2.beat": { bank: "voiceBank04", start: 362.638, finish: 364.863, speaker: "SERA", tape: false, radio: true, text: "SERA: Mast located on the saddle road. Hit the dish." },
	"radio.m14.p3.beat": { bank: "voiceBank04", start: 365.113, finish: 367.972, speaker: "SERA", tape: false, radio: true, text: "SERA: Perimeter CAP turning in. Four, in pairs, with raiders." },
	"radio.m14.p4.beat": { bank: "voiceBank04", start: 368.222, finish: 370.968, speaker: "SERA", tape: false, radio: true, text: "SERA: Hold the saddle. I'm listening for anything left alive." },
	"radio.m14.p4.chatter1": { bank: "voiceBank04", start: 371.218, finish: 373.551, speaker: "SERA", tape: false, radio: true, text: "SERA: More off the dark end of the row. Hold the orbit." },
	"radio.m14.p4.chatter2": { bank: "voiceBank05", start: 0.250, finish: 1.806, speaker: "SERA", tape: false, radio: true, text: "SERA: Nothing on the chain. Almost there." },
	"radio.m15.p1.beat": { bank: "voiceBank05", start: 2.056, finish: 3.813, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: Transmitting. Every second is a garrison." },
	"radio.m15.p1.chatter1": { bank: "voiceBank05", start: 4.063, finish: 6.193, speaker: "SERA", tape: false, radio: true, text: "SERA: Raiders inbound. Stay inside the volume." },
	"radio.m15.p1.chatter2": { bank: "voiceBank05", start: 6.443, finish: 8.017, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: Garrisons answering. Keep the volume." },
	"radio.m15.p1.hazard": { bank: "voiceBank05", start: 8.267, finish: 10.725, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: Link lost! Kill the two jammer trucks on the farm road." },
	"radio.m15.p2.beat": { bank: "voiceBank05", start: 10.975, finish: 14.647, speaker: "SERA", tape: false, radio: true, text: "SERA: Second wave, riding harder. Seven, in two groups. Raiders in tow." },
	"radio.m15.p3.beat": { bank: "voiceBank05", start: 14.897, finish: 17.402, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: Two reply beacons lit. Follow them to check the garrisons." },
	"radio.m15.p3.chatter1": { bank: "voiceBank05", start: 17.652, finish: 19.722, speaker: "LOYALIST", tape: false, radio: true, text: "LOYALIST: West garrison beacon confirmed. East is ahead." },
	"radio.m15.p4.beat": { bank: "voiceBank05", start: 19.972, finish: 23.541, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan both compounds for parked aircraft. Verify they stood down." },
	"radio.m15.p4.chatter1": { bank: "voiceBank05", start: 23.791, finish: 26.686, speaker: "SERA", tape: false, radio: true, text: "SERA: Engines cold at the first compound. Check the second." },
	"radio.m16.p1.beat": { bank: "voiceBank05", start: 26.936, finish: 29.331, speaker: "SERA", tape: false, radio: true, text: "SERA: River gates keep you under the storm. Stay low." },
	"radio.m16.p1.chatter1": { bank: "voiceBank05", start: 29.581, finish: 31.704, speaker: "SERA", tape: false, radio: true, text: "SERA: Last gate. The marked tanks are just past it." },
	"radio.m16.p2.beat": { bank: "voiceBank05", start: 31.954, finish: 35.223, speaker: "SERA", tape: false, radio: true, text: "SERA: Rain hides the markings. Scan both ends before you fire." },
	"radio.m16.p2.chatter1": { bank: "voiceBank05", start: 35.473, finish: 38.794, speaker: "SERA", tape: false, radio: true, text: "SERA: Fuel markings visible. Keep the farm roofs out of the strike." },
	"radio.m16.p3.beat": { bank: "voiceBank05", start: 39.044, finish: 40.948, speaker: "SERA", tape: false, radio: true, text: "SERA: Three silos under the storm. Burn them." },
	"radio.m16.p3.twist": { bank: "voiceBank05", start: 41.198, finish: 44.194, speaker: "SERA", tape: false, radio: true, text: "SERA: Five diving through the cloud. Finish the tanks and turn." },
	"radio.m16.p3.t1.beat": { bank: "voiceBank05", start: 44.444, finish: 47.344, speaker: "SERA", tape: false, radio: true, text: "SERA: Patrol riding the thunder. Five, in two groups." },
	"radio.m16.p4.beat": { bank: "voiceBank05", start: 47.594, finish: 49.675, speaker: "SERA", tape: false, radio: true, text: "SERA: Forward relay on the staging path. Cut it." },
	"radio.m16.p5.beat": { bank: "voiceBank05", start: 49.925, finish: 52.854, speaker: "SERA", tape: false, radio: true, text: "SERA: Hold over the relay. Its last traffic is still in the air." },
	"radio.m16.p5.chatter1": { bank: "voiceBank05", start: 53.104, finish: 55.956, speaker: "SERA", tape: false, radio: true, text: "SERA: Pair off the plateau, using the storm. Hold the orbit." },
	"radio.m16.p5.chatter2": { bank: "voiceBank05", start: 56.206, finish: 57.822, speaker: "SERA", tape: false, radio: true, text: "SERA: Second pair, coming out of the rain." },
	"radio.m17.p1.beat": { bank: "voiceBank05", start: 58.072, finish: 60.023, speaker: "SERA", tape: false, radio: true, text: "SERA: One dish under the aurora. Cut it." },
	"radio.m17.p2.beat": { bank: "voiceBank05", start: 60.273, finish: 62.909, speaker: "SERA", tape: false, radio: true, text: "SERA: Four intercepts lit by the aurora, in pairs." },
	"radio.m17.p3.beat": { bank: "voiceBank05", start: 63.159, finish: 65.488, speaker: "TEAL", tape: true, radio: true, text: "TEAL (tape): If you hear this up here, read the signature." },
	"radio.m17.p3.chatter1": { bank: "voiceBank05", start: 65.738, finish: 68.303, speaker: "SERA", tape: false, radio: true, text: "SERA: The archive is speaking. Signature decoding." },
	"radio.m17.p3.twist": { bank: "voiceBank05", start: 68.553, finish: 71.633, speaker: "SERA", tape: false, radio: true, text: "SERA: Archive lost. Jammer under the array. Find it, low." },
	"radio.m17.p3.t1.beat": { bank: "voiceBank05", start: 71.883, finish: 74.401, speaker: "SERA", tape: false, radio: true, text: "SERA: Get under the aurora glow. It'll show on the scan." },
	"radio.m17.p3.t1.chatter1": { bank: "voiceBank05", start: 74.651, finish: 76.722, speaker: "SERA", tape: false, radio: true, text: "SERA: There. A dish truck in the array's shadow." },
	"radio.m17.p3.t2.beat": { bank: "voiceBank05", start: 76.972, finish: 78.153, speaker: "SERA", tape: false, radio: true, text: "SERA: Jammer marked. Cut it." },
	"radio.m17.p3.t3.beat": { bank: "voiceBank05", start: 78.403, finish: 79.889, speaker: "SERA", tape: false, radio: true, text: "SERA: Its escort is up. Two." },
	"radio.m17.p3.t4.beat": { bank: "voiceBank05", start: 80.139, finish: 83.027, speaker: "SERA", tape: false, radio: true, text: "SERA: Archive's back. Hold the orbit. Read the signature." },
	"radio.m17.p3.t4.chatter1": { bank: "voiceBank05", start: 83.277, finish: 86.667, speaker: "SERA", tape: false, radio: true, text: "SERA: Signature decoding. Hold. It carries a Marshal's seal." },
	"radio.m18.p1.beat": { bank: "voiceBank05", start: 86.917, finish: 88.730, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: Climb into my lights, trainee." },
	"radio.m18.p1.chatter1": { bank: "voiceBank05", start: 88.980, finish: 91.779, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: Teal climbed faster. Show me more." },
	"radio.m18.p2.beat": { bank: "voiceBank05", start: 92.029, finish: 94.901, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Mark a clear pickup site. We need his answers alive." },
	"radio.m18.p2.chatter1": { bank: "voiceBank05", start: 95.151, finish: 97.548, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Ridge landing zone clear. We can bring a helo there." },
	"radio.m18.p3.beat": { bank: "voiceBank05", start: 97.798, finish: 100.165, speaker: "SERA", tape: false, radio: true, text: "SERA: His wingmen first. Four, in pairs." },
	"radio.m18.p4.beat": { bank: "voiceBank05", start: 100.415, finish: 102.602, speaker: "SERA", tape: false, radio: true, text: "He flies like Teal. Teal learned it from him." },
	"radio.m18.p4.twist": { bank: "voiceBank05", start: 102.852, finish: 106.242, speaker: "SERA", tape: false, radio: true, text: "SERA: Chute open. His wing is turning back. Cover the marines' pickup." },
	"radio.m18.p4.t1.beat": { bank: "voiceBank05", start: 106.492, finish: 109.631, speaker: "MARINE", tape: false, radio: true, text: "MARINE: We have him. Forty-five seconds to get him off the ridge." },
	"radio.m18.p4.t1.chatter1": { bank: "voiceBank05", start: 109.881, finish: 112.457, speaker: "SERA", tape: false, radio: true, text: "SERA: His second pair is diving on the pickup. Hold them." },
	"radio.m18.p4.t1.chatter2": { bank: "voiceBank05", start: 112.707, finish: 114.428, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Helo's spinning up. Almost out." },
	"radio.m18.p5.beat": { bank: "voiceBank05", start: 114.678, finish: 117.480, speaker: "MARINE", tape: false, radio: true, text: "MARINE: He is talking. Coast is recording. Hold the link." },
	"radio.m18.p5.chatter1": { bank: "voiceBank05", start: 117.730, finish: 121.157, speaker: "MARINE", tape: false, radio: true, text: "MARINE: He admits the handwriting. Coast is recording every word." },
	"radio.m18.ace.stage1": { bank: "voiceBank05", start: 121.407, finish: 125.703, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: I taught him that turn. Wing, show the trainee the answer." },
	"radio.m18.ace.stage2": { bank: "voiceBank05", start: 125.953, finish: 128.738, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: Last lesson. Wing, keep him busy." },
	"radio.m18.ace.return1": { bank: "voiceBank05", start: 128.988, finish: 131.496, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: Now. Again, trainee. From the top." },
	"radio.m18.ace.return2": { bank: "voiceBank05", start: 131.746, finish: 133.961, speaker: "VULTURE TWO", tape: false, radio: true, text: "VULTURE TWO: Head on. The way Teal never would." },
	"radio.m18.ace.call1": { bank: "voiceBank05", start: 134.211, finish: 137.232, speaker: "SERA", tape: false, radio: true, text: "SERA: VULTURE TWO pulled back to call his wing. 1 inbound." },
	"radio.m18.ace.call2": { bank: "voiceBank05", start: 137.482, finish: 140.635, speaker: "SERA", tape: false, radio: true, text: "SERA: VULTURE TWO pulled back to call his wing. 2 inbound." },
	"radio.m19.p1.beat": { bank: "voiceBank05", start: 140.885, finish: 143.364, speaker: "SERA", tape: false, radio: true, text: "SERA: Watch what the cranes unload. Mark the quays." },
	"radio.m19.p1.chatter1": { bank: "voiceBank05", start: 143.614, finish: 146.083, speaker: "SERA", tape: false, radio: true, text: "SERA: Those crates are munitions. The quays are military." },
	"radio.m19.p2.beat": { bank: "voiceBank05", start: 146.333, finish: 148.327, speaker: "SERA", tape: false, radio: true, text: "SERA: Three military quays. Hit the warehouses." },
	"radio.m19.p2.twist": { bank: "voiceBank05", start: 148.577, finish: 151.239, speaker: "SERA", tape: false, radio: true, text: "SERA: Early CAP pair launching. Finish the quay, then turn in." },
	"radio.m19.p2.t1.beat": { bank: "voiceBank05", start: 151.489, finish: 153.386, speaker: "SERA", tape: false, radio: true, text: "SERA: Early pair off the apron. Clear them." },
	"radio.m19.p3.beat": { bank: "voiceBank05", start: 153.636, finish: 157.005, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Follow the three quay beacons. Our launch needs a clear way out." },
	"radio.m19.p3.chatter1": { bank: "voiceBank05", start: 157.255, finish: 160.611, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: First bend clear. Last beacon marks the open channel." },
	"radio.m19.p4.beat": { bank: "voiceBank05", start: 160.861, finish: 164.069, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Workers aboard. Cover our launch clear of the burning quays." },
	"radio.m19.p4.chatter1": { bank: "voiceBank05", start: 164.319, finish: 167.058, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: All workers counted. Past the worst of the smoke." },
	"radio.m19.p5.beat": { bank: "voiceBank05", start: 167.308, finish: 169.997, speaker: "SERA", tape: false, radio: true, text: "SERA: Main CAP off the apron. Four, in two groups." },
	"radio.m19.p6.beat": { bank: "voiceBank05", start: 170.247, finish: 173.420, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Quays clear. Hold the channel while we count our people." },
	"radio.m19.p6.chatter1": { bank: "voiceBank05", start: 173.670, finish: 176.190, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: First crew answering. Still calling the eastern quay." },
	"radio.m20.p1.beat": { bank: "voiceBank05", start: 176.440, finish: 179.258, speaker: "SERA", tape: false, radio: true, text: "SERA: Full wing on the east line. Nine, in three groups." },
	"radio.m20.p2.beat": { bank: "voiceBank05", start: 179.508, finish: 182.282, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Paper is aboard. Scan the harbor exit before we move." },
	"radio.m20.p2.chatter1": { bank: "voiceBank05", start: 182.532, finish: 185.391, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Exit marked. We will move as soon as your scan is clear." },
	"radio.m20.p3.beat": { bank: "voiceBank05", start: 185.641, finish: 187.628, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Launch moving. Keep the sky quiet." },
	"radio.m20.p3.chatter1": { bank: "voiceBank05", start: 187.878, finish: 190.194, speaker: "SERA", tape: false, radio: true, text: "SERA: Western wing reacting. Launch is halfway out." },
	"radio.m20.p3.hazard": { bank: "voiceBank05", start: 190.444, finish: 193.304, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Guns on both banks, firing on the launch! Silence them!" },
	"radio.m20.p4.beat": { bank: "voiceBank05", start: 193.554, finish: 196.707, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Holding at the exit. Mark the patrol boat's approach beacons." },
	"radio.m20.p4.chatter1": { bank: "voiceBank05", start: 196.957, finish: 199.241, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Patrol boat sees your mark. One more beacon." },
	"radio.m20.p5.beat": { bank: "voiceBank05", start: 199.491, finish: 202.465, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Patrol boat alongside. Hold until the paper changes hands." },
	"radio.m20.p5.chatter1": { bank: "voiceBank05", start: 202.715, finish: 204.955, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Archive case passed. Tapes are next." },
	"radio.m21.p1.beat": { bank: "voiceBank05", start: 205.205, finish: 207.832, speaker: "SERA", tape: false, radio: true, text: "SERA: The dark canal keeps you off his radar. Follow it." },
	"radio.m21.p1.chatter1": { bank: "voiceBank05", start: 208.082, finish: 210.620, speaker: "SERA", tape: false, radio: true, text: "SERA: Relay above the apartments. Hit only the dish." },
	"radio.m21.p2.beat": { bank: "voiceBank05", start: 210.870, finish: 213.830, speaker: "SERA", tape: false, radio: true, text: "SERA: Low scan over the canal. Mark the dish above the roofs." },
	"radio.m21.p2.chatter1": { bank: "voiceBank05", start: 214.080, finish: 216.415, speaker: "SERA", tape: false, radio: true, text: "SERA: Dish marked. Apartment roofs stay standing." },
	"radio.m21.p3.beat": { bank: "voiceBank05", start: 216.665, finish: 219.095, speaker: "SERA", tape: false, radio: true, text: "SERA: Broadcast relay above the city. Dish only." },
	"radio.m21.p4.beat": { bank: "voiceBank05", start: 219.345, finish: 221.824, speaker: "SERA", tape: false, radio: true, text: "SERA: Escort flight scrambling. Four, in two pairs." },
	"radio.m21.p5.beat": { bank: "voiceBank05", start: 222.074, finish: 224.687, speaker: "SERA", tape: false, radio: true, text: "SERA: Hold over the tower. I want to hear nothing from it." },
	"radio.m21.p5.chatter1": { bank: "voiceBank05", start: 224.937, finish: 227.634, speaker: "SERA", tape: false, radio: true, text: "SERA: Pair off the dark side of the city. Hold the orbit." },
	"radio.m21.p5.chatter2": { bank: "voiceBank05", start: 227.884, finish: 229.031, speaker: "SERA", tape: false, radio: true, text: "SERA: Still silent. Hold it." },
	"radio.m21.p6.beat": { bank: "voiceBank05", start: 229.281, finish: 232.077, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Repair crew moving. Cover us to the dark district." },
	"radio.m21.p6.chatter1": { bank: "voiceBank05", start: 232.327, finish: 235.491, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Crew passing the canal bend. Keep the approach clear." },
	"radio.m21.p7.beat": { bank: "voiceBank05", start: 235.741, finish: 239.292, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Launch moored. Follow district lights to guide the shore crew." },
	"radio.m21.p7.chatter1": { bank: "voiceBank05", start: 239.542, finish: 242.432, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Shore crew sees your mark. Moving to the next street." },
	"radio.m22.p1.beat": { bank: "voiceBank05", start: 242.682, finish: 245.261, speaker: "SERA", tape: false, radio: true, text: "SERA: The fog depots carry his signature. Find them." },
	"radio.m22.p1.chatter1": { bank: "voiceBank05", start: 245.511, finish: 247.968, speaker: "SERA", tape: false, radio: true, text: "SERA: Permits match. Every depot is fuel." },
	"radio.m22.p2.beat": { bank: "voiceBank05", start: 248.218, finish: 250.142, speaker: "SERA", tape: false, radio: true, text: "SERA: Five depots in the fog. All marked." },
	"radio.m22.p3.beat": { bank: "voiceBank05", start: 250.392, finish: 253.249, speaker: "SERA", tape: false, radio: true, text: "SERA: Follow the pier beacons. Check the whole fuel line is cut." },
	"radio.m22.p3.chatter1": { bank: "voiceBank05", start: 253.499, finish: 255.903, speaker: "SERA", tape: false, radio: true, text: "SERA: West pier empty. Follow the lights to the east." },
	"radio.m22.p4.beat": { bank: "voiceBank05", start: 256.153, finish: 258.472, speaker: "SERA", tape: false, radio: true, text: "SERA: Patrol riding the fog. Four, in two pairs." },
	"radio.m22.p5.beat": { bank: "voiceBank05", start: 258.722, finish: 261.917, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Cannot see the piers. Cover us while we check the hoses." },
	"radio.m22.p5.chatter1": { bank: "voiceBank05", start: 262.167, finish: 265.402, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Inspectors at the central pier. Fuel line looks dry." },
	"radio.m22.p6.beat": { bank: "voiceBank05", start: 265.652, finish: 268.662, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Scan the last two piers. We need proof every hose is dry." },
	"radio.m22.p6.chatter1": { bank: "voiceBank05", start: 268.912, finish: 271.824, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: First hose disconnected. Check the eastern pier too." },
	"radio.m22.p7.beat": { bank: "voiceBank05", start: 272.074, finish: 275.055, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Hoses dry. Hold the link for the frigates to copy." },
	"radio.m22.p7.chatter1": { bank: "voiceBank05", start: 275.305, finish: 278.465, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Report copied. The escape fleet cannot refuel." },
	"radio.m23.p1.beat": { bank: "voiceBank05", start: 278.715, finish: 280.759, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Ring closing. Raiders on the bow." },
	"radio.m23.p1.chatter1": { bank: "voiceBank05", start: 281.009, finish: 283.439, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Second group off the platform. Hold them." },
	"radio.m23.p1.chatter2": { bank: "voiceBank05", start: 283.689, finish: 287.168, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Third group, low on the water. Two left in the ring." },
	"radio.m23.p2.beat": { bank: "voiceBank05", start: 287.418, finish: 291.066, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: One gap open. Scan the water before we close the ring." },
	"radio.m23.p2.chatter1": { bank: "voiceBank05", start: 291.316, finish: 293.479, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: No wake in the gap. Finish the sweep." },
	"radio.m23.p3.beat": { bank: "voiceBank05", start: 293.729, finish: 298.185, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Ring closed. Command flight launching. Four, from both sides." },
	"radio.m23.p4.beat": { bank: "voiceBank05", start: 298.435, finish: 301.825, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Follow the outer beacons. Check the whole sea lane is in sight." },
	"radio.m23.p4.chatter1": { bank: "voiceBank05", start: 302.075, finish: 305.370, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Western lane visible. Sweep to the eastern beacon." },
	"radio.m23.p5.beat": { bank: "voiceBank05", start: 305.620, finish: 308.995, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Inspection launch crossing. Cover it until it docks." },
	"radio.m23.p5.chatter1": { bank: "voiceBank05", start: 309.245, finish: 312.822, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Inspection launch halfway across. Gap remains clear." },
	"radio.m23.p6.beat": { bank: "voiceBank05", start: 313.072, finish: 316.560, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: No ships through. Hold the command link for the landing force." },
	"radio.m23.p6.chatter1": { bank: "voiceBank05", start: 316.810, finish: 319.030, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING FORCE: Ring report received. Bringing our boats forward." },
	"radio.m24.p1.beat": { bank: "voiceBank05", start: 319.280, finish: 321.808, speaker: "SERA", tape: false, radio: true, text: "SERA: Under the storm. Three gates to the platform." },
	"radio.m24.p1.chatter1": { bank: "voiceBank05", start: 322.058, finish: 324.142, speaker: "SERA", tape: false, radio: true, text: "SERA: Last gate. The deck stores are ahead." },
	"radio.m24.p2.beat": { bank: "voiceBank05", start: 324.392, finish: 326.316, speaker: "SERA", tape: false, radio: true, text: "SERA: Three stores on the deck. Burn them." },
	"radio.m24.p3.beat": { bank: "voiceBank05", start: 326.566, finish: 329.488, speaker: "SERA", tape: false, radio: true, text: "SERA: Patrol in the storm shadow. Five, in two groups." },
	"radio.m24.p4.beat": { bank: "voiceBank05", start: 329.738, finish: 333.310, speaker: "SERA", tape: false, radio: true, text: "SERA: Scan below the cloud. The tanker is hiding behind the deck smoke." },
	"radio.m24.p4.chatter1": { bank: "voiceBank05", start: 333.560, finish: 336.426, speaker: "SERA", tape: false, radio: true, text: "SERA: Engine heat below the cloud. It is running for the coast." },
	"radio.m24.p5.beat": { bank: "voiceBank05", start: 336.676, finish: 339.710, speaker: "SERA", tape: false, radio: true, text: "SERA: Tanker jet lifting off, running for the coast. Stop it." },
	"radio.m24.p5.chatter1": { bank: "voiceBank05", start: 339.960, finish: 341.838, speaker: "SERA", tape: false, radio: true, text: "SERA: Tanker's halfway to the coast. Close on it." },
	"radio.m24.p5.chatter2": { bank: "voiceBank05", start: 342.088, finish: 343.827, speaker: "SERA", tape: false, radio: true, text: "SERA: He's almost over the city. Now!" },
	"radio.m24.p6.beat": { bank: "voiceBank05", start: 344.077, finish: 347.750, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Deck crew aboard. Cover them clear of the burning stores." },
	"radio.m24.p6.chatter1": { bank: "voiceBank05", start: 348.000, finish: 351.050, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Launch halfway clear. Deck crew accounted for." },
	"radio.m24.p7.beat": { bank: "voiceBank05", start: 351.300, finish: 354.298, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: Tanker down. Hold while we check for other launches." },
	"radio.m24.p7.chatter1": { bank: "voiceBank05", start: 354.548, finish: 358.403, speaker: "FRIGATE", tape: false, radio: true, text: "FRIGATE: No second tanker on radar. Checking the last deck returns." },
	"radio.m25.p1.beat": { bank: "voiceBank05", start: 358.653, finish: 360.570, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: Beach in eighty seconds. Keep them off us." },
	"radio.m25.p1.chatter1": { bank: "voiceBank05", start: 360.820, finish: 363.424, speaker: "SERA", tape: false, radio: true, text: "SERA: Second intercept launching. Stay on the craft." },
	"radio.m25.p1.chatter2": { bank: "voiceBank05", start: 363.674, finish: 365.055, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: Surf line. Ramps going down." },
	"radio.m25.p2.beat": { bank: "voiceBank05", start: 365.305, finish: 368.339, speaker: "SERA", tape: false, radio: true, text: "SERA: First intercept off the apron. Three, in two groups." },
	"radio.m25.p3.beat": { bank: "voiceBank05", start: 368.589, finish: 370.961, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: Ramps down. Scan both exits so we can leave the sand." },
	"radio.m25.p3.chatter1": { bank: "voiceBank05", start: 371.211, finish: 373.167, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: West exit clear. Check the eastern street." },
	"radio.m25.p4.beat": { bank: "voiceBank06", start: 0.250, finish: 3.172, speaker: "SERA", tape: false, radio: true, text: "SERA: Second wave with raiders, coming round behind. Hold the beach." },
	"radio.m25.p5.beat": { bank: "voiceBank06", start: 3.422, finish: 5.553, speaker: "SERA", tape: false, radio: true, text: "SERA: Beach relay is still directing fire. Cut it." },
	"radio.m25.p6.beat": { bank: "voiceBank06", start: 5.803, finish: 8.888, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: Streets reached. Hold for both beach exits to answer." },
	"radio.m25.p6.chatter1": { bank: "voiceBank06", start: 9.138, finish: 11.492, speaker: "LANDING CRAFT", tape: false, radio: true, text: "LANDING CRAFT: West exit answering. Waiting for the eastern squad." },
	"radio.m26.p1.beat": { bank: "voiceBank06", start: 11.742, finish: 14.635, speaker: "SERA", tape: false, radio: true, text: "SERA: Wing splits. Four ahead; the rest will come round behind." },
	"radio.m26.p1.group1": { bank: "voiceBank06", start: 14.885, finish: 16.617, speaker: "SERA", tape: false, radio: true, text: "SERA: Second flight on your six! Turn!" },
	"radio.m26.p2.beat": { bank: "voiceBank06", start: 16.867, finish: 20.397, speaker: "SERA", tape: false, radio: true, text: "SERA: Signal bouncing between roofs. Scan low to narrow it down." },
	"radio.m26.p2.chatter1": { bank: "voiceBank06", start: 20.647, finish: 23.725, speaker: "SERA", tape: false, radio: true, text: "SERA: Rooftop echoes mapped. We still need the name of the mast." },
	"radio.m26.p3.beat": { bank: "voiceBank06", start: 23.975, finish: 27.201, speaker: "TEAL", tape: true, radio: true, text: "TEAL (tape): He'll be where he can hear himself. The parliament mast." },
	"radio.m26.p3.chatter1": { bank: "voiceBank06", start: 27.451, finish: 30.036, speaker: "SERA", tape: false, radio: true, text: "SERA: Triangulating. He's above the parliament transmitter." },
	"radio.m26.p3.chatter2": { bank: "voiceBank06", start: 30.286, finish: 32.170, speaker: "SERA", tape: false, radio: true, text: "SERA: Fix is closing. Stay in the volume." },
	"radio.m26.p4.beat": { bank: "voiceBank06", start: 32.420, finish: 35.860, speaker: "SERA", tape: false, radio: true, text: "SERA: Loyalists marked a corridor. Follow two lights into the city." },
	"radio.m26.p4.chatter1": { bank: "voiceBank06", start: 36.110, finish: 39.276, speaker: "SERA", tape: false, radio: true, text: "SERA: Loyalists see your lights. Follow the last city beacon." },
	"radio.m26.p5.beat": { bank: "voiceBank06", start: 39.526, finish: 42.405, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Secure the quay while witnesses board. Cover the marked site." },
	"radio.m26.p5.chatter1": { bank: "voiceBank06", start: 42.655, finish: 47.257, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Witnesses boarding. Quay remains secure." },
	"radio.m26.p6.beat": { bank: "voiceBank06", start: 47.507, finish: 50.492, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Witnesses aboard. Keep us covered until parliament is in sight." },
	"radio.m26.p6.chatter1": { bank: "voiceBank06", start: 50.742, finish: 52.877, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Parliament in sight. Witnesses still aboard." },
	"radio.m27.p1.beat": { bank: "voiceBank06", start: 53.127, finish: 54.694, speaker: "SERA", tape: false, radio: true, text: "His wingmen first. Then him." },
	"radio.m27.p2.beat": { bank: "voiceBank06", start: 54.944, finish: 56.922, speaker: "SERA", tape: false, radio: true, text: "SERA: His relay is still broadcasting. Cut it." },
	"radio.m27.p2.twist": { bank: "voiceBank06", start: 57.172, finish: 60.833, speaker: "RUSK", tape: false, radio: true, text: "RUSK: You cut one relay. Every loyal pilot still hears me. On me, now." },
	"radio.m27.p2.t1.beat": { bank: "voiceBank06", start: 61.083, finish: 63.979, speaker: "SERA", tape: false, radio: true, text: "SERA: His last escort pair is forming on him. Clear them." },
	"radio.m27.p3.beat": { bank: "voiceBank06", start: 64.229, finish: 67.603, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Mark the clear road below him. We need Rusk alive to answer." },
	"radio.m27.p3.chatter1": { bank: "voiceBank06", start: 67.853, finish: 70.790, speaker: "MARINE", tape: false, radio: true, text: "MARINE: Clear road marked. We are ready to take him into custody." },
	"radio.m27.p4.beat": { bank: "voiceBank06", start: 71.040, finish: 74.275, speaker: "SERA", tape: false, radio: true, text: "That's his jet. Teal's voice on his tapes. Bring him down." },
	"radio.m27.p5.beat": { bank: "voiceBank06", start: 74.525, finish: 77.610, speaker: "SERA", tape: false, radio: true, text: "SERA: Rusk is down. Follow three lights to Teal's broadcast line." },
	"radio.m27.p5.chatter1": { bank: "voiceBank06", start: 77.860, finish: 80.892, speaker: "SERA", tape: false, radio: true, text: "SERA: One more light. Above it, the whole coast can hear you." },
	"radio.m27.p6.beat": { bank: "voiceBank06", start: 81.142, finish: 83.148, speaker: "SERA", tape: false, radio: true, text: "SERA: You're on every frequency. Say it your way." },
	"radio.m27.p6.chatter1": { bank: "voiceBank06", start: 83.398, finish: 85.652, speaker: "SERA", tape: false, radio: true, text: "SERA: Last of his diehards. Keep them off the signal." },
	"radio.m27.p6.chatter2": { bank: "voiceBank06", start: 85.902, finish: 88.582, speaker: "HARBOR", tape: false, radio: true, text: "HARBOR: Loyalist pilots answering. Every harbor." },
	"radio.m27.ace.stage1": { bank: "voiceBank06", start: 88.832, finish: 93.154, speaker: "RUSK", tape: false, radio: true, text: "RUSK: Every relay says I am the law. Yours is a child's radio. Wing!" },
	"radio.m27.ace.stage2": { bank: "voiceBank06", start: 93.404, finish: 96.881, speaker: "RUSK", tape: false, radio: true, text: "RUSK: Teal obeyed until the one order that mattered. Wing, finish him." },
	"radio.m27.ace.return1": { bank: "voiceBank06", start: 97.131, finish: 98.968, speaker: "SERA", tape: false, radio: true, text: "SERA: Rusk is turning back in. Here he comes." },
	"radio.m27.ace.return2": { bank: "voiceBank06", start: 99.218, finish: 100.908, speaker: "RUSK", tape: false, radio: true, text: "RUSK: Then hear it from me. Head on." },
	"radio.m27.ace.call2": { bank: "voiceBank06", start: 101.158, finish: 103.656, speaker: "SERA", tape: false, radio: true, text: "SERA: AIR MARSHAL RUSK pulled back to call his wing. 2 inbound." },
	"radio.m27.ace.call3": { bank: "voiceBank06", start: 103.906, finish: 106.597, speaker: "SERA", tape: false, radio: true, text: "SERA: AIR MARSHAL RUSK pulled back to call his wing. 3 inbound." },
};
